import{_ as o,a0 as p,w as n,s as d,ao as s,I as e,x as r,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const R=JSON.parse('{"title":"將操作系統移植到新的芯片架構的經驗 | LCTT x X-CMD","titleTemplate":false,"description":"將操作系統移植到新的芯片架構的經驗 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"將操作系統移植到新的芯片架構的經驗 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"將操作系統移植到新的芯片架構的經驗 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210527 Port operating systems to new chip architectures","title":"將操作系統移植到新的芯片架構的經驗","tag":"202105","desc":""},"relativePath":"202105/20210527 Port operating systems to new chip architectures.md","filePath":"[post].md"}'),u={name:"202105/20210527 Port operating systems to new chip architectures.md"};function T(m,t,h,f,b,C){const l=p("Link");return n(),d("div",null,[t[35]||(t[35]=s('<h1 id="將操作系統移植到新的芯片架構的經驗" tabindex="-1">將操作系統移植到新的芯片架構的經驗 <a class="header-anchor" href="#將操作系統移植到新的芯片架構的經驗" aria-label="Permalink to “將操作系統移植到新的芯片架構的經驗”">​</a></h1><blockquote><p>在將嵌入式系統操作系統移植到不同的芯片架構時，RT-Thread 的維護者們從中學到了什麼。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202105/28/221925tuv6j9lsg6xovog2.jpg" alt=""></p><p>曾經有人問我，為什麼計算機被稱為“計算機”，它們做的事情可遠不止計算數字。一台現代的個人電腦可以瀏覽互聯網、播放音頻和視頻、為視頻遊戲和電影生成漂亮的圖形、模擬和預測複雜的天氣模式和流行病風險、將建築和工程藍圖變為現實等等。</p><p>計算機之所以能做到這些，是因為所有這些問題都可以歸結為數字方程，而計算機的 CPU —— 其中央處理單元 —— 實際上不過是一個簡單的計算器。</p><p>為了讓 CPU 向硬盤驅動器發送信號以寫入數據，或向顯示器發送信號以顯示圖像，它必須接收指令。這些指令是以 “代碼” 的形式出現的，這是一種簡明的説法，即必須有人寫一個 <em>程序</em> ，與CPU “説” 同樣的語言。CPU 理解的是 <em>機器語言</em>，這是一個大多數人都無法理解的比特陣列，大多數人都不可能手動寫出來。相反，我們使用像 C、C++、Java、Python 等編程語言。這些語言被解析並編譯成機器語言，然後交付給 CPU。</p>',6)),e("p",null,[t[2]||(t[2]=r("如果你試圖用一種它不理解的語言來指示 CPU，它不知道該怎麼做。你可以通過嘗試用 ",-1)),a(l,{href:"https://www.redhat.com/en/store/red-hat-enterprise-linux-developer-suite"},{default:i(()=>[...t[0]||(t[0]=[r("x86_64 RHEL",-1)])]),_:1}),t[3]||(t[3]=r(" 鏡像啓動 ",-1)),a(l,{href:"https://opensource.com/resources/raspberry-pi"},{default:i(()=>[...t[1]||(t[1]=[r("樹莓派",-1)])]),_:1}),t[4]||(t[4]=r(" 來體驗這種誤傳嘗試的尷尬結果。如果它能工作就好了，但是不能。",-1))]),t[36]||(t[36]=e("h3",{id:"將一個操作系統移植到一個新的架構上",tabindex:"-1"},[r("將一個操作系統移植到一個新的架構上 "),e("a",{class:"header-anchor",href:"#將一個操作系統移植到一個新的架構上","aria-label":"Permalink to “將一個操作系統移植到一個新的架構上”"},"​")],-1)),e("p",null,[a(l,{href:"https://opensource.com/article/20/6/open-source-rtos"},{default:i(()=>[...t[5]||(t[5]=[r("RT-Thread 項目",-1)])]),_:1}),t[6]||(t[6]=r(" 為嵌入式系統程序員提供了一個開源的操作系統（OS）。嵌入式領域是非常多樣化的，有很多物聯網（IoT）、定製工業和業餘設備。RT-Thread 的目標是使嵌入式編程對每個人來説都很容易，無論你使用什麼設備。有時，這意味着要將一個操作系統移植到一個新的架構上，不管是用於相同架構但指令集略有不同的的芯片，還是用於全新的架構。",-1))]),e("p",null,[t[8]||(t[8]=r("一開始處理這個問題可能會有點嚇人 —— 你可能不知道從哪裏開始或如何開始。這篇文章收集了 RT-Thread 維護者在將 ",-1)),a(l,{href:"https://www.rt-thread.io/"},{default:i(()=>[...t[7]||(t[7]=[r("RTOS",-1)])]),_:1}),t[9]||(t[9]=r(" 移植到新的芯片架構時學到的經驗。",-1))]),t[37]||(t[37]=s('<h3 id="你在開始之前需要知道什麼" tabindex="-1">你在開始之前需要知道什麼 <a class="header-anchor" href="#你在開始之前需要知道什麼" aria-label="Permalink to “你在開始之前需要知道什麼”">​</a></h3><p>這裏是一個看似難以逾越的過程的高屋建瓴的觀點。這對你的項目來説可能有所不同，但從概念上來説，這是相對普遍的，即使一些具體的細節是不同的：</p><ol><li>準備好一個 C 語言的執行環境</li><li>確認可以通過串行端口發送和接收字符</li><li>確認上下文切換代碼可以工作</li><li>獲取支持的硬件定時器</li><li>確認中斷程序可以通過串口接收和解析數據</li></ol><h3 id="執行模式" tabindex="-1">執行模式 <a class="header-anchor" href="#執行模式" aria-label="Permalink to “執行模式”">​</a></h3><p>對於大多數先進的體系結構，操作系統和用户應用程序運行在不同的權限級別上。這可以防止有功能故障的代碼影響操作系統的集成和安全。例如，在 ARMv7-A 架構中，操作系統通常在系統模式下運行，而在 ARMv8-A 中，操作系統可以在 EL2 或 EL3 權限級別上運行。</p><p>通常情況下，芯片在通電時以最高權限級別執行啓動代碼。但在此之後，操作系統會將特權級別切換到其目標模式。</p><h4 id="_1、執行-c-代碼" tabindex="-1">1、執行 C 代碼 <a class="header-anchor" href="#_1、執行-c-代碼" aria-label="Permalink to “1、執行 C 代碼”">​</a></h4>',7)),e("p",null,[t[12]||(t[12]=r("這一步的關鍵動作是將 ",-1)),e("ruby",null,[a(l,{href:"https://en.wikipedia.org/wiki/.bss"},{default:i(()=>[...t[10]||(t[10]=[r("塊起始符號",-1)])]),_:1}),t[11]||(t[11]=e("rt",null,"block starting symbol",-1))]),t[13]||(t[13]=r("（.bss）部分設置為零，並設置堆棧指針。",-1))]),t[38]||(t[38]=s('<p>在 C 語言的實現中，未初始化的全局變量和靜態變量通常存儲在 .bss 部分，它不佔用存儲設備的任何空間。當程序被加載時，相應的空間被分配到內存中，並被初始化為零。當操作系統啓動時，它必須自己做這項工作。</p><p>另一方面，操作系統必須初始化堆棧空間並設置堆棧指針。由於 C 語言程序在進入和退出函數時在堆棧上保存和恢復局部變量，所以在調用任何 C 函數之前必須設置堆棧指針。RT-Thread 必須為每個新創建的線程做這個步驟。</p><h4 id="_2、至少使用一個串行驅動器" tabindex="-1">2、至少使用一個串行驅動器 <a class="header-anchor" href="#_2、至少使用一個串行驅動器" aria-label="Permalink to “2、至少使用一個串行驅動器”">​</a></h4><p>RT-Thread 通過串口輸出信息和日誌，這也有助於在移植過程中對代碼進行調試。在這個階段，通過串口 <em>接收</em> 數據是不必要的。當我們第一次在串口上看到我們友好的、熟悉的 RT-Thread 的標誌時，我們就知道我們走對了路！</p><h4 id="_3、確認上下文切換邏輯" tabindex="-1">3、確認上下文切換邏輯 <a class="header-anchor" href="#_3、確認上下文切換邏輯" aria-label="Permalink to “3、確認上下文切換邏輯”">​</a></h4><p>一個任務的上下文是它的整個執行環境，它包含通用寄存器、程序計數器、堆棧幀的位置等等。當一個新的線程被創建時，RT-Thread 必須手動分配和設置它的上下文，這樣調度器就可以切換到新的線程，就像它對其他線程一樣。</p><p>有三件事需要注意：</p><ul><li>首先，當 RT-Thread 啓動時，默認情況下中斷是禁用的。當任務調度器第一次被啓用時，它們就會被啓用；這個過程是在上下文切換期間用匯編語言實現的。</li><li>第二，當一個線程退出時，下一個調度將開始，這時擁有的資源會被空閒的線程回收。</li><li>第三，數據被推入堆棧的順序必須與從堆棧中彈出數據的順序一致。</li></ul><p>一般來説，你希望正常進入主函數和 msh 控制台。然而，在這個階段無法實現輸入控制，因為串行輸入中斷還沒有實現。當串行中斷實現後，就可以進行 msh 輸入了。</p><h4 id="_4、設置定時器" tabindex="-1">4、設置定時器 <a class="header-anchor" href="#_4、設置定時器" aria-label="Permalink to “4、設置定時器”">​</a></h4><p>RT-Thread 需要一個定時器來定期產生中斷；它被用來計算自系統啓動以來所經過的“滴答”。計數器的編號用於提供軟件中斷功能，並指示內核何時開始調度一個任務。</p><p>設置時間片的值可能是一件棘手的事情。它通常是 10ms 到 1ms。如果你在一個慢速的 CPU 上選擇一個小的時間片，大部分時間就會花在任務切換上 —— 不利於完成其他事情。</p><h4 id="_5、確認串口工作正常" tabindex="-1">5、確認串口工作正常 <a class="header-anchor" href="#_5、確認串口工作正常" aria-label="Permalink to “5、確認串口工作正常”">​</a></h4><p>在這一步，我們通過串口與 RT-Thread msh 進行交互。我們發送命令，按回車鍵，然後看着 msh 執行命令並顯示結果。</p><p>這個過程通常不難實現。不過，有一點要提醒大家。在某些平台上，在處理完串口中斷後，別忘了清除中斷標誌。</p><p>一旦串口工作正常，移植過程基本上就完成了。</p><h3 id="實踐" tabindex="-1">實踐 <a class="header-anchor" href="#實踐" aria-label="Permalink to “實踐”">​</a></h3><p>為了將你的項目移植到不同的芯片架構上，你需要非常清楚地瞭解你所針對的芯片的架構。熟悉你的項目中最關鍵的部分的底層代碼。通過對照芯片的手冊結合大量的實際工作經驗，你會了解芯片的特權模式、寄存器和編譯方法。</p>',18)),e("p",null,[t[15]||(t[15]=r("如果你沒有需要移植到新芯片的項目，請加入我們；RT-Thread 項目總是需要幫助將 RTOS 移植到新的芯片上！作為一個開源項目，RT-Thread 正在改變開源嵌入式編程的面貌。請在 ",-1)),a(l,{href:"https://club.rt-thread.io/"},{default:i(()=>[...t[14]||(t[14]=[r("RT-Thread 俱樂部",-1)])]),_:1}),t[16]||(t[16]=r("介紹你自己並尋求幫助!",-1))]),t[39]||(t[39]=e("hr",null,null,-1)),e("p",null,[t[18]||(t[18]=r("本文基於 DEV 社區上的 ",-1)),a(l,{href:"https://dev.to/abby06/how-to-port-operating-system-to-different-chip-architecture-3od9"},{default:i(()=>[...t[17]||(t[17]=[r("如何將操作系統移植到不同的芯片架構上？",-1)])]),_:1}),t[19]||(t[19]=r("，並經許可轉載。",-1))]),t[40]||(t[40]=e("hr",null,null,-1)),e("p",null,[t[21]||(t[21]=r("via: ",-1)),a(l,{href:"https://opensource.com/article/21/5/port-chip-architectures"},{default:i(()=>[...t[20]||(t[20]=[r("https://opensource.com/article/21/5/port-chip-architectures",-1)])]),_:1})]),e("p",null,[t[26]||(t[26]=r("作者：",-1)),a(l,{href:"https://opensource.com/users/alansmithee"},{default:i(()=>[...t[22]||(t[22]=[r("Alan Smithee",-1)])]),_:1}),t[27]||(t[27]=r(" 選題：",-1)),a(l,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[23]||(t[23]=[r("lujun9972",-1)])]),_:1}),t[28]||(t[28]=r(" 譯者：",-1)),a(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[24]||(t[24]=[r("wxy",-1)])]),_:1}),t[29]||(t[29]=r(" 校對：",-1)),a(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[25]||(t[25]=[r("wxy",-1)])]),_:1})]),e("p",null,[t[32]||(t[32]=r("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[30]||(t[30]=[r("LCTT",-1)])]),_:1}),t[33]||(t[33]=r(" 原創編譯，",-1)),a(l,{href:"https://linux.cn/"},{default:i(()=>[...t[31]||(t[31]=[r("Linux中國",-1)])]),_:1}),t[34]||(t[34]=r(" 榮譽推出",-1))])])}const g=o(u,[["render",T]]);export{R as __pageData,g as default};
